UPDATE "pages" SET "blocks" = "blocks" || $json$[
  {"id":23001,"type":"Texto","eyebrow":"Do something here","title":"Maia is not just context — it has a whole life of its own","description":"Fly a small aircraft, watch horses thunder around an 800-metre track, meet a crocodile in the city centre or disappear into thirty hectares of woodland. Our complete activity map separates the things you can do any week from annual events that require a date in the diary.","ctaLabel":"Open the complete Maia activity map","ctaUrl":"/blog/things-to-do-in-maia-activity-map","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb WHERE "slug"='blog-what-and-where-is-maia';

INSERT INTO "pages" ("slug", "title", "blocks", "status", "updated_at") VALUES
('blog-things-to-do-in-maia-activity-map', 'Things to do in Maia: the complete activity map', $json$[
  {"id":23101,"type":"Hero","eyebrow":"The useful Maia map","title":"Things to do in Maia: from tiny zoo to open sky","description":"Planes, horses, crocodiles, comic theatre, woodland, local fairs and festivals that occasionally get gloriously out of hand. This is Maia as a place to do things — with maps, official sources and honest ticket advice.","seoTitle":"Things to Do in Maia: Activities, Maps & Tickets","seoDescription":"Explore Maia’s parks, zoo, aerodrome, horse events, museums, theatre and festivals with Google Maps, official sources and ticket links.","seoKeywords":["things to do in Maia","Maia activities","visit Maia Portugal","Maia events","Zoo da Maia","Parque de Avioso","Fórum da Maia"],"imageUrl":"/blog/maia-overview.webp","imageAlt":"Torre Lidador and Maia City Hall in the centre of Maia","imageCaption":"Maia is six kilometres north of Porto and considerably less predictable than the airport transfer suggests.","imageCredit":"Photo: Pedrovsk · CC BY-SA 3.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Maia_Camara_Municipal.jpg","background":"#11110f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":23102,"type":"Texto","eyebrow":"Start here","title":"How to use this guide without turning fun into admin","description":"Permanent places come first; seasonal events follow. Opening times, prices and programmes change, so use the official button before leaving home. The map button opens the exact place in Google Maps. If tickets exist, we link to the venue or recognised ticket office — never to a mystery reseller with a logo designed in five minutes.","ctaLabel":"Open Visit Maia’s live agenda","ctaUrl":"https://www.visitmaia.pt/experiencias/todoseventos","secondaryCtaLabel":"See Maia on Google Maps","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Maia%2C+Portugal","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":23103,"type":"Texto","eyebrow":"Nature · Free","title":"Parque de Avioso: thirty hectares and room to breathe","description":"Three walking routes move through woods, open areas and the landscape around the source of Ribeira de Avioso. There is a playground, environmental interpretation, parking and a café terrace. The park opens every day; its two gates keep seasonal hours, so check the official page instead of trusting a three-year-old review written by somebody called DragonSlayer92.","imageUrl":"/blog/maia-green.webp","imageAlt":"Historic house and green gardens at Quinta da Gruta in Maia","imageCaption":"Green Maia includes large parks, rural routes and environmental spaces such as Quinta da Gruta.","imageCredit":"Photo: Maieutica · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Quinta_da_Gruta_-_Frente.jpg","ctaLabel":"Hours and official information","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/parque-de-avioso","secondaryCtaLabel":"Open Parque de Avioso map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Parque+de+Avioso%2C+Maia","background":"#174f3b","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23104,"type":"Texto","eyebrow":"Family · Tickets","title":"Zoo da Maia: the small zoo with a serious reptile problem","description":"In the city centre, Maia’s compact zoo reports more than 330 animals across 110 species, plus a reptile house, skeleton collection and free-flight bird demonstrations. It is intimate rather than epic — useful with children and strange enough for adults who enjoy meeting an iguana before lunch. Buy through the zoo’s official ticket office; online tickets may not include local discounts.","ctaLabel":"Official zoo and tickets","ctaUrl":"https://www.zoodamaia.pt/","secondaryCtaLabel":"Open Zoo da Maia map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Zoo+da+Maia","background":"#6d4d28","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23105,"type":"Texto","eyebrow":"Aviation · Booking","title":"Vilar de Luz: learn to fly before promising to jump","description":"The municipal aerodrome is home to the Aero Club do Porto, flight training and aircraft services. Nortávia currently advertises an ‘Aluno por Um Dia’ experience: ground instruction followed by a one-hour flight in a Cessna 152 with an instructor. The aerodrome also hosts Air Invictus, aviation exhibitions and occasional flight experiences. Official tourism material mentions skydiving facilities, but confirm the currently authorised operator directly before paying for any parachute voucher. The sky is exciting; consumer disputes are not.","imageUrl":"/blog/maia-gateway.webp","imageAlt":"Aircraft gateway and aviation infrastructure in Maia","imageCaption":"Maia’s relationship with aviation extends from the international airport to Vilar de Luz aerodrome.","imageCredit":"Photo: Robot8A · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Aeroporto_Francisco_S%C3%A1_Carneiro.jpeg","ctaLabel":"Book a verified flying experience","ctaUrl":"https://www.nortavia.com/servicos","secondaryCtaLabel":"Open aerodrome map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Aer%C3%B3dromo+Municipal+de+Vilar+de+Luz","background":"#243b6b","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23106,"type":"Texto","eyebrow":"Horses · Events and lessons","title":"Hipódromo Municipal: racing, jumping and proper horse theatre","description":"The Maia equestrian centre uses an 800-metre sand track, paddock, grandstand, cross-country course and training arenas. It hosts national competition, Maia Summer Race and the annual Feira do Cavalo, where jumping, dressage, working equitation, carriage driving and spectacle share the programme. For lessons or day-to-day access, contact the Centro Equestre; for event dates, check Visit Maia before travelling.","ctaLabel":"Official equestrian information","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/centro-equestre-da-maia","secondaryCtaLabel":"Open hipódromo map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Hip%C3%B3dromo+Municipal+da+Maia","background":"#5b321d","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23107,"type":"Texto","eyebrow":"Culture · Tickets","title":"Fórum da Maia: exhibitions, concerts and comedy with teeth","description":"The Fórum is Maia’s main cultural engine: galleries, a large auditorium, outdoor stage and café theatre in a building by José Carlos Loureiro. The annual International Comic Theatre Festival brings clowning, mime, circus, improvisation and sharp political humour from several countries. Maia Fest Music, Maia BD, cinema, magic, World Press Photo and family theatre also rotate through the programme. Paid events normally use the official Fórum da Maia BOL page; some passes and accessible seating are sold only at the physical box office.","ctaLabel":"Official ticket office","ctaUrl":"https://forummaia.bol.pt/","secondaryCtaLabel":"Open Fórum da Maia map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=F%C3%B3rum+da+Maia","background":"#7a2035","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23108,"type":"Texto","eyebrow":"History · Mostly free","title":"Museum, Quinta da Gruta and Torre Lidador: read Maia vertically","description":"Begin at the Museum of History and Ethnology of Terra da Maia for archaeology, rural tools, linen and the daily work behind local identity. Cross into Quinta da Gruta for gardens and environmental education. Back in the city, guided visits to the 92-metre Torre Lidador provide the useful shock of seeing just how metropolitan — and how green — Maia really is. Museum activities and tower visits may require advance registration.","imageUrl":"/blog/maia-museum.webp","imageAlt":"Museum of History and Ethnology of Terra da Maia","imageCaption":"The territory museum turns ordinary tools into a much longer story of Maia.","imageCredit":"Photo: Cyberlima785 · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Museu_da_Maia.jpg","ctaLabel":"Book a Torre Lidador visit","ctaUrl":"https://visitmaia.pt/experiencias/descobrir/visita-comentada-a-torre-lidador","secondaryCtaLabel":"Open museum map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Museu+de+Hist%C3%B3ria+e+Etnologia+da+Terra+da+Maia","background":"#38291f","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23109,"type":"Texto","eyebrow":"Walk · Cycle · Skate","title":"Move through Maia instead of merely arriving in it","description":"The PR3 Products of the Land route is a short circular walk through farms and rural lanes. Parque de Avioso supports walking and informal sport; the Vilar de Luz area connects aviation landscape with cycling; Cidade Desportiva adds skateboarding, athletics and municipal facilities. These are not packaged thrills. They are places locals actually use — which is generally a good sign.","ctaLabel":"Open the official PR3 route","ctaUrl":"https://visitmaia.pt/produtos-turisticos/percursos-na-maia-pr3-rota-produtos-da-terra","secondaryCtaLabel":"Open Cidade Desportiva map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Cidade+Desportiva+da+Maia","background":"#174f3b","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23110,"type":"Texto","eyebrow":"July · Mostly free","title":"Festas da Maia: eleven days when the city stops pretending to be quiet","description":"The annual July celebrations spread across Jardim das Pirâmides, Praça do Fórum and the city centre. Music, folklore, street animation, a procession, fireworks, the craft fair and book fair all overlap. Much of the programme is free. Dates and performers change every year, so use the municipal agenda rather than building a holiday around last year’s poster.","ctaLabel":"Check the current Maia events calendar","ctaUrl":"https://www.visitmaia.pt/experiencias/todoseventos","secondaryCtaLabel":"Open Jardim das Pirâmides map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Jardim+das+Pir%C3%A2mides%2C+Maia","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"},
  {"id":23111,"type":"Texto","eyebrow":"Save these seasons","title":"The annual events worth planning around","description":"Spring brings Maia International Acro Cup, cinema, Maia Fest Music, Maia BD and the Beer Market. June and July add Air Invictus, outdoor music, Festas da Maia, Festival Panda and Maia Symphonic. September is strong for blues, electronic music and the Feira do Cavalo. Autumn brings Comic Theatre, World Press Photo, magic and illustration; winter closes around Maia Natal. Some are free, some ticketed, and some will sell out. The official annual agenda is the source of truth.","ctaLabel":"Download the official 2026 agenda","ctaUrl":"https://visitmaia.pt/assets/files/eventos/Agenda2026.pdf","secondaryCtaLabel":"Open central Maia map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Pra%C3%A7a+Dr.+Jos%C3%A9+Vieira+de+Carvalho%2C+Maia","background":"#11110f","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":23112,"type":"Texto","eyebrow":"Our honest shortlist","title":"If you only have one day","description":"Start Saturday morning at Feira da Maia if the timing works. Continue to the museum and Quinta da Gruta, walk in Parque de Avioso after lunch, then return to the Fórum for an exhibition or performance. Families can swap the museum for the zoo; aviation obsessives should plan Vilar de Luz in advance; horse people already know where they are going. Everybody else should leave enough empty time for something unplanned — Maia rewards curiosity more than checklists.","ctaLabel":"Read our Maia introduction","ctaUrl":"/blog/what-and-where-is-maia","secondaryCtaLabel":"Open Maia Welcome Center map","secondaryCtaUrl":"https://www.google.com/maps/search/?api=1&query=Maia+Welcome+Center","background":"#8d2b20","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now())
